package ro.leo.keypad;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;
/** Runs in the IME package with a real editor/InputConnection, no text logging. */
public final class ImeSettingsTests extends Instrumentation {
    private void awaitInput(final int mode,final int inputClass)throws Exception{for(int attempt=0;attempt<80;attempt++){final boolean[] ready={false};runOnMainSync(new Runnable(){public void run(){try{Class<?> type=Class.forName("android.app.ActivityThread");Object thread=type.getMethod("currentActivityThread").invoke(null);java.lang.reflect.Field services=type.getDeclaredField("mServices");services.setAccessible(true);for(Object service:((java.util.Map<?,?>)services.get(thread)).values())if(service instanceof KeypadIme){java.lang.reflect.Field m=KeypadIme.class.getDeclaredField("mode"),i=KeypadIme.class.getDeclaredField("inputClass"),e=KeypadIme.class.getDeclaredField("editing");m.setAccessible(true);i.setAccessible(true);e.setAccessible(true);ready[0]=e.getBoolean(service)&&m.getInt(service)==mode&&i.getInt(service)==inputClass;}}catch(Exception failure){throw new RuntimeException(failure);}}});if(ready[0])return;SystemClock.sleep(100);}throw new AssertionError("IME editor binding did not become ready");}
    public void onCreate(Bundle args){start();}
    public void onStart(){Bundle result=new Bundle();EditorTestActivity activity=null;try{final EditorTestActivity[] opened={null};Application app=(Application)getTargetContext().getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){if(a instanceof EditorTestActivity)opened[0]=(EditorTestActivity)a;}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);try{getTargetContext().startActivity(new Intent(getTargetContext(),EditorTestActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));for(int i=0;i<80&&opened[0]==null;i++)SystemClock.sleep(100);activity=opened[0];if(activity==null)throw new AssertionError("editor did not resume");}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);}final EditorTestActivity editor=activity;for(int i=0;i<40&&!activity.hasWindowFocus();i++)SystemClock.sleep(100);waitForIdleSync();awaitInput(1,android.text.InputType.TYPE_CLASS_TEXT);sendKeyDownUpSync(KeyEvent.KEYCODE_2);SystemClock.sleep(650);sendKeyDownUpSync(KeyEvent.KEYCODE_2);SystemClock.sleep(650);waitForIdleSync();if(!"AA".contentEquals(editor.text.getText())){result.putInt("fixture_length",editor.text.length());Class<?> threadClass=Class.forName("android.app.ActivityThread");Object thread=threadClass.getMethod("currentActivityThread").invoke(null);java.lang.reflect.Field services=threadClass.getDeclaredField("mServices");services.setAccessible(true);for(Object service:((java.util.Map<?,?>)services.get(thread)).values())if(service instanceof KeypadIme)for(String name:new String[]{"mode","commitDelay","inputClass","editing","password"}){java.lang.reflect.Field value=KeypadIme.class.getDeclaredField(name);value.setAccessible(true);result.putString(name,String.valueOf(value.get(service)));}throw new AssertionError("configured ABC / 500 ms did not produce two separate letters");}
        runOnMainSync(new Runnable(){public void run(){editor.onNewIntent(new Intent().putExtra("field","password"));}});awaitInput(0,android.text.InputType.TYPE_CLASS_TEXT);sendKeyDownUpSync(KeyEvent.KEYCODE_2);SystemClock.sleep(650);sendKeyDownUpSync(KeyEvent.KEYCODE_2);SystemClock.sleep(650);waitForIdleSync();if(!"aa".contentEquals(editor.password.getText()))throw new AssertionError("password did not retain lowercase non-predictive mode");
        runOnMainSync(new Runnable(){public void run(){editor.onNewIntent(new Intent().putExtra("field","numeric"));}});awaitInput(1,android.text.InputType.TYPE_CLASS_PHONE);for(int key:new int[]{KeyEvent.KEYCODE_2,KeyEvent.KEYCODE_2,KeyEvent.KEYCODE_2,KeyEvent.KEYCODE_POUND,KeyEvent.KEYCODE_STAR})sendKeyDownUpSync(key);waitForIdleSync();if(!"222#*".contentEquals(editor.number.getText()))throw new AssertionError("numeric passthrough changed");result.putString("result","PASS actual InputConnection: configured ABC, 500ms letter commit, password non-predictive, numeric passthrough");
    }catch(Throwable failure){result.putString("error",android.util.Log.getStackTraceString(failure));}finally{if(activity!=null){final EditorTestActivity editor=activity;runOnMainSync(new Runnable(){public void run(){editor.text.setText("");editor.number.setText("");editor.password.setText("");editor.finish();}});}}
    finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
